		}

		// Only create if family has no categories
		const existing = await this.getFamilyCategories(familyId);
		if (existing.length > 0) {
			return; // Family already has categories
		}

		// Insert default categories directly using the DEFAULT_CATEGORIES constant
		// This ensures we always use the latest category list
		const categoriesToInsert = DEFAULT_CATEGORIES.map((cat) => ({
			family_id: familyId,
			name: cat.name,
			color: cat.color
		}));

		const { error } = await this.supabase.from('categories').insert(categoriesToInsert);

		// Ignore unique constraint violations (23505) - categories already exist
		if (error && error.code !== '23505') {
			throw new Error(error.message);
		}
	}

	/**
	 * Create a new custom category
	 *
	 * @param familyId - Family ID
	 * @param name - Category name
	 * @param color - Optional hex color code (#RRGGBB)
	 * @returns Created category
	 *
	 * Specification: #{#exp3a} Requirements 4, 7, 8
	 */
	async createCategory(familyId: string, name: string, color?: string): Promise<Category> {
		// Validation
		if (!familyId) {
			throw new Error('Family ID is required');
		}

		if (!name || name.trim() === '') {
			throw new Error('Category name is required');
		}

		if (name.length > 100) {
			throw new Error('Category name must be 100 characters or less');
		}

		// Validate color format if provided
		if (color !== undefined && color !== null && color !== '') {
			if (!this.isValidHexColor(color)) {
				throw new Error('Invalid color format. Use hex format: #RRGGBB');
			}
		}

		// Insert category
		const { data, error } = await this.supabase
			.from('categories')
			.insert({
				family_id: familyId,
				name: name.trim(),
				color: color || null
			})
			.select()
			.single();

		if (error) {
			// Handle unique constraint violation
			if (error.code === '23505') {
				throw new Error('A category with this name already exists in this family');
			}
			throw new Error(error.message);
		}

		return data;
	}

	/**
	 * Update an existing category
	 *
	 * @param categoryId - Category ID to update
	 * @param name - New category name
	 * @param color - New color (optional)
	 * @returns Updated category
	 *
	 * Specification: #{#exp3a} Requirement 5
	 */
	async updateCategory(categoryId: string, name: string, color?: string): Promise<Category> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		if (!name || name.trim() === '') {
			throw new Error('Category name is required');
		}

		if (name.length > 100) {
			throw new Error('Category name must be 100 characters or less');
		}

		// Validate color format if provided
		if (color !== undefined && color !== null && color !== '') {
			if (!this.isValidHexColor(color)) {
				throw new Error('Invalid color format. Use hex format: #RRGGBB');
			}
		}

		const updateData: CategoryUpdateData = {
			name: name.trim(),
			updated_at: new Date().toISOString()
		};

		if (color !== undefined) {
			updateData.color = color;
		}

		const { data, error } = await this.supabase
			.from('categories')
			.update(updateData)
			.eq('id', categoryId)
			.select()
			.single();

		if (error) {
			// Handle unique constraint violation
			if (error.code === '23505') {
				throw new Error('A category with this name already exists in this family');
			}
			throw new Error(error.message);
		}

		return data;
	}

	/**
	 * Delete a category
	 *
	 * @param categoryId - Category ID to delete
	 *
	 * Specification: #{#exp3a} Requirement 6
	 */
	async deleteCategory(categoryId: string): Promise<void> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		const { error } = await this.supabase.from('categories').delete().eq('id', categoryId);

		if (error) {
			throw new Error(error.message);
		}
	}

	/**
	 * Check if a category has associated expenses
	 *
	 * @param categoryId - Category ID to check
	 * @returns True if category has expenses, false otherwise
	 *
	 * Specification: #{#exp3a} Requirement 6
	 */
	async categoryHasExpenses(categoryId: string): Promise<boolean> {
		if (!categoryId) {
			throw new Error('Category ID is required');
		}

		const { data, error } = await this.supabase
			.from('expense_categories')
			.select('receipt_id')
			.eq('category_id', categoryId);

		if (error) {
			throw new Error(error.message);
		}

		return data && data.length > 0;
	}

	/**
	 * Validate hex color format
	 *
	 * @param color - Color string to validate
	 * @returns True if valid hex color
	 *
	 * Specification: #{#exp3a} Requirement 8
	 */
	private isValidHexColor(color: string): boolean {
		const hexColorRegex = /^#[0-9A-Fa-f]{6}$/;
		return hexColorRegex.test(color);
	}
}

